import sys,random,json,time
sys.path.insert(0,'submission');sys.path.insert(0,'tmp')
from protocol import validate
from te.session import run_case
from verify_replay_strict import verify_request

def paths_for(n,adj,s,t,maxp=50):
 out=[]
 def dfs(u,path,seen):
  if len(out)>=maxp:return
  if u==t:
   if path:out.append(list(path))
   return
  if len(path)>=12:return
  for v,e in adj.get(u,[]):
   if v not in seen:
    seen.add(v);path.append(e);dfs(v,path,seen);path.pop();seen.remove(v)
    if len(out)>=maxp:return
 dfs(s,[],{s});return out

def gen_case():
 n=random.randint(2,32)
 chain=[(i,i+1) for i in range(n-1)]
 used=set(chain)
 cand=[(u,v) for u in range(n) for v in range(n) if u!=v and (u,v) not in used]
 random.shuffle(cand)
 pairs=chain+cand[:random.randint(0,64-len(chain))]
 random.shuffle(pairs)
 edges=[[u,v,random.choice([0,1,1,2,10,100,1000])] for u,v in pairs]
 E=len(edges);adj={u:[] for u in range(n)}
 for e,(u,v) in enumerate(pairs):adj[u].append((v,e))
 K=random.randint(0,24)
 coms=[];alls=[];tot=0
 for k in range(K):
  s=0;t=n-1
  poss=paths_for(n,adj,s,t)
  random.shuffle(poss)
  T=min(8,len(poss),96-tot,random.randint(0,8))
  g=[]
  for j in range(T):g.append(list(poss.pop()) if random.random()<.85 else None)
  tot+=T
  coms.append({'source':s,'sink':t,'demand':random.choice([0,1,2,10,1000]),'paths':g})
  alls.append(poss)
 W=random.randint(1,8)
 ass=[[] for _ in range(W)]
 for k in range(K):ass[random.randrange(W)].append(k)
 workers=[sorted(a) for a in ass]
 maxlag=random.randint(0,12);quorum=random.randint(1,W)
 b=random.randint(1,16);a=random.randint(b,min(16,2*b-1))
 mode=random.choice(['route','admit'])
 events=[];issued=[];saves=[];tidx=0;tickets=list(range(0,500));random.shuffle(tickets);names=list(range(1000,1200));random.shuffle(names)
 nissues=random.randint(0,12);nevents=random.randint(1,80)
 for i in range(nevents):
  op=random.choice(['issue','deliver','step','audit','retune','save','restore','configure'])
  if op=='issue' and tidx>=nissues:op='audit'
  if op=='deliver' and not issued:op='step'
  if op=='restore' and not saves:op='audit'
  if op=='issue':
   events.append({'op':'issue','id':tickets[tidx],'worker':random.randrange(W)});issued.append(tickets[tidx]);tidx+=1
  elif op=='deliver':events.append({'op':'deliver','id':random.choice(issued)})
  elif op=='step':events.append({'op':'step'})
  elif op=='audit':events.append({'op':'audit'})
  elif op=='retune':events.append({'op':'retune','rho':random.randint(1,8)})
  elif op=='save':
   nm=names.pop();saves.append(nm);events.append({'op':'save','name':nm})
  elif op=='restore':events.append({'op':'restore','name':random.choice(saves)})
  else:
   cap=[];inds=list(range(E));random.shuffle(inds)
   for e in inds[:random.randint(0,min(10,E))]:cap.append([e,random.choice([0,1,2,10,1000])])
   dem=[];inds=list(range(K));random.shuffle(inds)
   for k in inds[:random.randint(0,min(5,K))]:dem.append([k,random.choice([0,1,10,1000])])
   pathchg=[]
   for k in random.sample(range(K),random.randint(0,min(3,K))):
    T=len(coms[k]['paths']);cand=alls[k][:];random.shuffle(cand);g=[]
    for j in range(T):g.append(list(cand.pop()) if cand and random.random()<.8 else None)
    for j in range(T):pathchg.append([k,j,g[j]])
   events.append({'op':'configure','mode':random.choice(['route','admit']),'capacity':cap,'demand':dem,'paths':pathchg})
 return {'nodes':n,'edges':edges,'commodities':coms,'workers':workers,'quorum':quorum,'max_lag':maxlag,'relax':[a,b],'rho':random.randint(1,8),'mode':mode,'events':events}

random.seed(1977)
t0=time.time()
for trial in range(3000):
 cases=[gen_case() for _ in range(random.choices([0,1,1,2,3],[1,5,5,2,1])[0])]
 req={'cases':cases};validate(req)
 out={'cases':[run_case(c) for c in cases]}
 try:verify_request(req,out)
 except Exception as e:
  import traceback;traceback.print_exc();open('tmp/large_fail.json','w').write(json.dumps(req));open('tmp/large_fail_out.json','w').write(json.dumps(out));print('FAIL',trial,e);break
 if trial%250==0:print('trial',trial,'sec',time.time()-t0)
else:print('ALL LARGE RANDOM OK',time.time()-t0)
